function ih($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function ij(array $v):string{return (string)json_encode($v,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);}
function ilint_content(string $content):array{$t=tempnam(sys_get_temp_dir(),'mrlapp_');file_put_contents($t,$content);$o=shell_exec('php -l '.escapeshellarg($t).' 2>&1');@unlink($t);$o=is_string($o)?trim($o):'';return ['ok'=>strpos($o,'No syntax errors detected')!==false,'detail'=>$o];}
function ilint_file(string $p):array{$o=shell_exec('php -l '.escapeshellarg($p).' 2>&1');$o=is_string($o)?trim($o):'';return ['ok'=>strpos($o,'No syntax errors detected')!==false,'detail'=>$o];}
function iatomic(string $p,string $c):bool{$t=$p.'.tmp_'.getmypid().'_'.date('Ymd_His');if(@file_put_contents($t,$c,LOCK_EX)===false)return false;@chmod($t,0644);if(!@rename($t,$p)){@unlink($t);return false;}@chmod($p,0644);return true;}
function icheck(array &$c,string $l,bool $ok,bool $req,string $d=''):void{$c[]=['label'=>$l,'status'=>$ok?'PASS':'FAIL','required'=>$req,'detail'=>$d];}
function idecode(array $p):array{$o=[];foreach($p as $rel=>$b){$d=base64_decode((string)$b,true);if(!is_string($d))return [];$o[$rel]=$d;}return $o;}
function ipre(string $doc,array $payloads):array{$c=[];icheck($c,'Installer running from /public_html/_installers',basename(__DIR__)==='_installers'&&basename(dirname(__DIR__))==='public_html',true,__DIR__);icheck($c,'race_results folder exists',is_dir($doc.'/race_results'),true,$doc.'/race_results');icheck($c,'race_results folder writable',is_writable($doc.'/race_results'),true,$doc.'/race_results');foreach(['config.php','config_mrl.php','class.user.php','race_results/payouts_helper.php','race_results/payouts.php','Paid_Status_Year.php'] as $f)icheck($c,'Required file: '.$f,is_file($doc.'/'.$f),true,$doc.'/'.$f);$d=idecode($payloads);icheck($c,'Embedded production files decoded',count($d)===count($payloads),true,count($d).' files');foreach($d as $rel=>$content){$l=ilint_content($content);icheck($c,'php -l candidate: '.$rel,$l['ok'],true,$l['detail']);icheck($c,'Candidate SHA-256: '.$rel,true,false,hash('sha256',$content));}$ok=true;foreach($c as $x)if($x['required']&&$x['status']!=='PASS'){$ok=false;break;}return ['ok'=>$ok,'checks'=>$c,'decoded'=>$d];}
