function itable(PDO $dbo,string $t):bool{$s=$dbo->prepare('SHOW TABLES LIKE :name');$s->execute([':name'=>$t]);return (bool)$s->fetchColumn();}
function iapply(string $doc,string $backupRoot,string $sessionFile,array $payloads):array{$pre=ipre($doc,$payloads);if(!$pre['ok'])return ['ok'=>false,'stage'=>'PRECHECK','checks'=>$pre['checks']];require_once $doc.'/config.php';if(!isset($dbo)||!($dbo instanceof PDO))return ['ok'=>false,'stage'=>'APPLY','message'=>'PDO database connection is unavailable.'];$stamp=date('Ymd_His');$bd=$backupRoot.'/install_admin_paid_payouts_v001_'.$stamp;if(!is_dir($bd)&&!@mkdir($bd,0775,true))return ['ok'=>false,'stage'=>'APPLY','message'=>'Could not create backup directory.'];$new=[];$modified=[];$backups=[];foreach($pre['decoded'] as $rel=>$content){$target=$doc.'/'.$rel;if(is_file($target)){$bp=$bd.'/'.$rel;if(!is_dir(dirname($bp))&&!@mkdir(dirname($bp),0775,true))return ['ok'=>false,'stage'=>'APPLY','message'=>'Could not create file backup directory.'];if(!@copy($target,$bp))return ['ok'=>false,'stage'=>'APPLY','message'=>'Could not back up '.$rel.'.'];$modified[]=$rel;$backups[$rel]=$bp;}else{$new[]=$rel;}}try{$tables=idb($dbo);}catch(Throwable $e){return ['ok'=>false,'stage'=>'APPLY','message'=>'Could not create financial tables: '.$e->getMessage()];}foreach($pre['decoded'] as $rel=>$content)if(!iatomic($doc.'/'.$rel,$content))return ['ok'=>false,'stage'=>'APPLY','message'=>'Could not write '.$rel.'.'];$session=['installer'=>'install_admin_paid_payouts_v001','applied_at'=>date('c'),'backup_dir'=>$bd,'new_files'=>$new,'modified_files'=>$modified,'backups'=>$backups,'tables'=>$tables,'rollback_note'=>'Rollback restores/removes production files but preserves financial database tables/data.'];if(!is_dir($backupRoot))@mkdir($backupRoot,0775,true);iatomic($sessionFile,ij($session)."
");$c=[];foreach($pre['decoded'] as $rel=>$content){$target=$doc.'/'.$rel;icheck($c,'Installed file exists: '.$rel,is_file($target),true,$target);$l=ilint_file($target);icheck($c,'Installed php -l: '.$rel,$l['ok'],true,$l['detail']);icheck($c,'Installed SHA-256: '.$rel,hash_file('sha256',$target)===hash('sha256',$content),true,(string)hash_file('sha256',$target));}foreach($tables as $t)icheck($c,'Database table exists: '.$t,itable($dbo,$t),true,$t);$ok=true;foreach($c as $x)if($x['required']&&$x['status']!=='PASS'){$ok=false;break;}return ['ok'=>$ok,'stage'=>'POSTCHECK','checks'=>$c,'modified_files'=>$modified,'new_files'=>$new,'database_tables'=>$tables,'session'=>$session];}
function irollback(string $doc,string $sessionFile):array{$c=[];if(!is_file($sessionFile)){icheck($c,'Rollback session available',false,true,'No prior installer session found.');return ['ok'=>false,'stage'=>'ROLLBACK','checks'=>$c];}$s=json_decode((string)file_get_contents($sessionFile),true);if(!is_array($s))$s=[];foreach(($s['modified_files']??[]) as $rel){$bp=(string)($s['backups'][$rel]??'');$ok=$bp!==''&&is_file($bp)&&iatomic($doc.'/'.$rel,(string)file_get_contents($bp));icheck($c,'Restored: '.$rel,$ok,true,$bp);}foreach(($s['new_files']??[]) as $rel){$p=$doc.'/'.$rel;$ok=!is_file($p)||@unlink($p);icheck($c,'Removed new file: '.$rel,$ok,true,$p);}icheck($c,'Financial database tables preserved',true,false,'Rollback intentionally does not drop tables or delete financial data.');$ok=true;foreach($c as $x)if($x['required']&&$x['status']!=='PASS'){$ok=false;break;}return ['ok'=>$ok,'stage'=>'ROLLBACK','checks'=>$c];}
$action=(string)($_POST['action']??'');if($action==='apply')$result=iapply($docRoot,$backupRoot,$sessionFile,$payloads);elseif($action==='rollback')$result=irollback($docRoot,$sessionFile);else{$pre=ipre($docRoot,$payloads);$result=['ok'=>$pre['ok'],'stage'=>'PRECHECK','checks'=>$pre['checks'],'modified_files'=>[],'new_files'=>array_keys($payloads)];}
